import re
lines = open('/app/dataset/genealogy_trees.txt', encoding='utf-8').read().split('\n')
grid = lines[5:110]
# distribution of name rows
from collections import Counter
c = Counter()
for r, line in enumerate(grid):
    for m in re.finditer(r'[^\W\d_]{2,}', line, re.UNICODE):
        c[r] += 1
for r in range(len(grid)):
    if c[r]: print(f'grid row {r:3d}: {c[r]} words')
"

